+void Invert_Disc (Object)
+OBJECT *Object;
+  {
+  ((DISC *)Object)->Inverted = 1 - ((DISC *)Object)->Inverted;
+  }
+
+void Transform_Disc (Object, Trans)
+OBJECT *Object;
+TRANSFORM *Trans;
+  {
+  DISC *Disc = (DISC *)Object;
