+  /* Convert the X Coordinate to be a DBL from 0.0 to 1.0 */
+  X_Scalar = (x - (DBL) width / 2.0) / (DBL) width;
+
+  /* Convert the Y Coordinate to be a DBL from 0.0 to 1.0 */
+  Y_Scalar = (( (DBL)(Frame.Screen_Height - 1) - y) -
+    (DBL) height / 2.0) / (DBL) height;
