+  VScale (Temp_Vect_1, Frame.Camera->Up, Y_Scalar);
+  VScale (Temp_Vect_2, Frame.Camera->Right, X_Scalar);
+  VAdd (ray->Direction, Temp_Vect_1, Temp_Vect_2);
+  VAdd (ray->Direction, ray->Direction, Frame.Camera->Direction);
