+        Red = Green = Blue = (unsigned char)(grey * maxclr);
+        }
+      else 
+        {
+        Red = (unsigned char) (Previous_Line[x].Red * maxclr);
+        Green = (unsigned char) (Previous_Line[x].Green * maxclr);
+        Blue = (unsigned char) (Previous_Line[x].Blue * maxclr);
