+  if (v->coef[v->ord] < 0.0) 
+    {
+    for (k = u->ord - v->ord - 1; k >= 0; k -= 2)
+      r->coef[k] = -r->coef[k];
+    for (k = u->ord - v->ord; k >= 0; k--)
+      for (j = v->ord + k - 1; j >= k; j--)
