+#declare Chars_Inc_Temp=version
+#version 2.0
+
+// CHARS.INC R2.0
+// Characters for POV-RAY V2.0
+// An including file.
+// Original by Ken Maeno 1992-93
+// Revised and extended by Chris Young
+//
+// This file includes 26 upper-case letter and other characters defined 
+// as objects. The size of all characters is 4 * 5 * 1. The center of the 
+// bottom side of a character face is set to the origin, so please 
+// translate a character appropriately before rotating it about 
+// the x or z axes.
+// 	Usage:
+//
+// 	object{ 
+// 	  char_A
+//	  pigment{ color Red }
+//	}
+//
+
+#declare char_A = 
+ intersection {
+   box{<-2,0,-0.1>,<2,5,1.1>}
+   union { 
+     box{<-0.5,-6,0>,<0.5,0,1> rotate  z*16.699 }
+     box{<-0.5,-6,0>,<0.5,0,1> rotate -z*16.699 }
+     box{<-1,  -4,0>,<1, -3,1> }
+     translate y*5
+   }
+   bounded_by{ box { <-2,0,0>,<2,5,1> } }
+ }
+
+#declare char_P = 
+  union {
+    difference{
+      cylinder{0*z,z,1.5}
+      cylinder{-z,2*z,0.5}
+      plane{x,0}
+      bounded_by{ box { <0,-1.5,0>, <1.5, 1.5, 1> } }
+      translate<0.5, 3.5, 0>
+    }
+    box{ <-1, 4, 0>, <0.5, 5, 1> }
+    box{ <-1, 2, 0>, <0.5, 3, 1> }
+    box{ <-2, 0, 0>, <-1, 5, 1 > }
+  }
+
+#declare char_B = 
+  union {
+    object{char_P}
+    difference{
+      cylinder{0*z,z,1.5}
+      cylinder{-z,2*z,0.5}
+      plane{x,0}
+      bounded_by{ box { <0,-1.5,0>, <1.5, 1.5, 1> } }
+      translate<0.5, 1.5, 0>
+    }
+    box{ <-1, 0, 0>, <0.5, 1, 1> }
+  }
+
+#declare char_C = 
+  union {
+    difference{
+      cylinder{0*z,z,2}
+      cylinder{-z,2*z,1}
+      plane{y,0}
+      bounded_by{ box { <-2,0,0>, <2,2,1> } }
+      translate 3*y
+    }
+    difference{
+      cylinder{0*z,z,2}
+      cylinder{-z,2*z,1}
+      plane{-y,0}
+      bounded_by{ box { <-2,-2,0>, <2,0,1> } }
+      translate 2*y
+    }
+    box{ <-2,2,0>,<-1,3,1> }
+  }
+
+#declare char_D = 
+  union {
+    difference{
+      cylinder{0*z,z,2.5}
+      cylinder{-z,2*z,1.5}
+      plane{x,0}
+      bounded_by{ box { <0,-2.5,0>, <2.5,2.5,1> } }
+      translate <-0.5,2.5,0>
+    }
+    box{ <-1,4,0>,<-0.5,5,1> }
+    box{ <-1,0,0>,<-0.5,1,1> }
+    box{ <-2,0,0>,<-1,  5,1> }
+  }
+
+#declare char_F = 
+  union {
+    box{ <-2,0,0>,<-1,5,1> }
+    box{ <-1,2,0>,<1.5,3,1> }
+    box{ <-1,4,0>,<2,5,1> }
+  }
+
+#declare char_E = 
+  union {
+    object{char_F}
+    box{ <-1,0,0>,<2,1,1> }
+  }
+
+#declare char_G = 
+  union {
+    object{char_C}
+    box{ < 0,1.5,0>,<2,2.3,1> }
+  }
+
+#declare char_H = 
