+
+      if (status < 0) 
+        {
+        finished = TRUE;
+        break;
+        }
+
+      Image->iwidth  = buffer[4] | (buffer[5] << 8);
+      Image->iheight = buffer[6] | (buffer[7] << 8);
+      Image->width = (DBL) Image->iwidth;
+      Image->height = (DBL) Image->iheight;
