+        return(0);
+
+      setvbuf (handle->file, handle->buffer, _IOFBF, buffer_size);
+      }
+
+    for (i = 0 ; i < 12 ; i++)
+      if (getc(handle->file) == EOF)
+        return(0);
+
+    if (((data1 = getc(handle->file)) == EOF)
+      || ((data2 = getc(handle->file)) == EOF))
+      return(0);
+
+    *width  = data2 * 256 + data1;
+
+    if (((data1 = getc(handle->file)) == EOF)
+      || ((data2 = getc(handle->file)) == EOF))
+      return(0);
+
+    for (i = 0 ; i < 2 ; i++)
+      if (getc(handle->file) == EOF)
